+func TestBalanceMultipleEntries(t *testing.T) {
+	l := &Ledger{}
+
+	// Credit of 300 to account "a", balanced by -300 to "other"
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: 300, Currency: "EUR"},
+		Entry{AccountID: "other", AmountCents: -300, Currency: "EUR"},
