+		t.Fatal(err)
+	}
+
+	// Debit of 100 from account "a", balanced by +100 to "other2"
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: -100, Currency: "EUR"},
+		Entry{AccountID: "other2", AmountCents: 100, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+
